  const svc = await service();
  for (const delta of [0, 1.5, '2', NaN, undefined]) {
    await assert.rejects(svc.adjustStock('widget', delta, 'r'), ValidationError);
  }
  for (const reason of ['', '  ', undefined, 3]) {
