  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 6 }]);
  await assert.rejects(svc.adjustStock('widget', -5, 'r'), err =>
    err instanceof InsufficientStockError && err.requested === 5 && err.available === 4);
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 6, sold: 0 });
  assert.equal((await svc.adjustStock('widget', -4, 'r')).stock, 6);
});

test('adjustStock is safe alongside concurrent reserve/release', async () => {
  const svc = await service({ widget: 20 });
  const ops = [];
  for (let i = 0; i < 10; i++) {
    ops.push(svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]).then(() => svc.release(`o${i}`)));
    ops.push(svc.adjustStock('widget', i % 2 ? 1 : -1, 'r'));
  }
  await Promise.all(ops);
  const s = await svc.snapshot('widget');
  assert.equal(s.reserved, 0);
  assert.equal(s.stock, 20);
});
